(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["br"] = {"ui":{"skip":"Mont d'an endalc'hadoù","back":"← Distro da AI-gile","lang.button":"Yezh: {name}","lang.dialog":"Dibab ur yezh","lang.search":"Klask yezhoù","lang.none":"Yezh ebet ne glot","lang.notYet":"{name} n'eo ket bet treset c'hoazh","theme.aria":"Cheñch etre an tem sklaer hag an tem teñval","theme.toLight":"Cheñch d'an tem sklaer","theme.toDark":"Cheñch d'an tem teñval","index.title":"AI-gile: ho skipailh diorren AI, war un daolenn","index.description":"AI-gile zo un daolenn kanban evit skipailhoù AI a god. Labourat a reont p'emaoc'h o kousket; ur bern berr traoù da zivizout, da amprouiñ ha da asantiñ a vo evidoc'h.","hero.logoAlt":"Arlun taolenn AI-gile","hero.h1.html":"Ho skipailh diorren AI, war un&nbsp;daolenn.","hero.alpha":"🐣 Pre-alfa serret","hero.alphaTitle":"Abred ha n'eo ket echu: trugarez da glask anezhañ!","hero.lede":"Savet e vez ganto p'emaoc'h o kousket. Dihunet e vefec'h gant ur bern berr: un nebeut goulennoù, un nebeut traoù da amprouiñ, un diamant mouk pe zaou. Klik, asantet, distro d'ho kafe.","dl.windows":"Arload Windows","dl.browser":"Lañsañ en ho merdeer","dl.soon":"Dont a ra abred","dl.notify":"🔔 Lavarit din p'en em zigor","dl.notifySmall":"Alfa pe beta","hero.secondary":"Agile, met ar skipailh n'en deus ket ezhomm eus ur c'hafe stand-up morse. (Stand-up a reont koulskoude.)","pitch.h2":"AI-gile e kement a c'her ha ma karot","pitch.lede":"Dibabit ul hirder, diwar ur ger betek 144. Pep hirder zo ur zeskrivadenn, skrivet evit ar vent-se. Riklit ar riklenn pe implijit an alc'hwezioù-saeta.","pitch.rangeLabel":"Hirder e gerioù","pitch.dice":"🎲 ur stumm all","pitch.words.one":"{n} ger","pitch.words.other":"{n} ger","pitch.letters.one":"{n} lizherenn","pitch.letters.other":"{n} lizherenn","pitch.chars.one":"{n} arouez","pitch.chars.other":"{n} arouez","count.line.html.one":"{n} kartenn war an daolenn bremañ","count.line.html.other":"{n} kartenn war an daolenn bremañ","features.aria":"Ar pezh a ra","f.pile.h":"Ur bern evidoc'h","f.pile.html":"<b>Evidoc'h</b> a dastum pep tra a c'hortoz ac'hanoc'h, dre an holl raktresoù: goulennoù, traoù da amprouiñ, labourioù n'hall ober nemet un den. Ho renkad a lavar petra zo da heul ha pet pad a ra.","f.sleep.h":"Skipailhoù a labour p'emaoc'h o kousket","f.sleep.p":"Pep raktres en deus ur penn-skipailh hag ur skipailh ajanted AI. Skrivit un evezhiadenn war ur gartenn ha dihuniñ a ra ar skipailh, ober a ra al labour hag e kas en-dro deoc'h gant pazennoù a c'hall heuliañ un den skuizh.","f.tester.h":"Un amprouer AI a wiriekaat da gentañ","f.tester.p":"Kent ma'z afe tra ebet betek ac'hanoc'h, un amprouer a heul ar pazennoù en un eilad eus an arload hag a ziskouez ar pezh en deus gwelet, gant ur skeudenn skramm. Lenit buan ar re a zo aet mat hag asantit ho klik.","f.proof.h":"Pruvoù, n'eo ket promesaoù","f.proof.p":"Pep treuzkas a ziskouez ar pezh zo cheñchet: ar restroù, an diforc'hioù, ar skeudennoù skramm. Dre ret n'eo ket digeriñ pep arload evit gouzout hag-eñ eo echu.","f.chat.h":"Flapañ gant ho pennoù-skipailh","f.chat.p":"Ur varrenn evel Discord: un arlun dre raktres, diamantoù mouk evit ar pezh en deus ezhomm ac'hanoc'h. Kasit ur mennozh d'ur penn-skipailh; e kartennoù hag e blan e troio, gant ur bouton ✅ Go.","f.tidy.h":"Mirout urzh en-unan","f.tidy.p":"Ar c'hartennoù kar a vez kenstrollet en unan, an titloù mesk a vez reizhet, ha gwiriañ an tokenoù a vir ar c'hod skañv. Nebeutoc'h a draoù da cheñch etrezo, nebeutoc'h da soñjal.","f.private.h":"Ho re, war hoc'h urzhiater","f.private.li1":"An daolenn a red war ho jestr deoc'h-c'hwi hag a respont deoc'h hepken.","f.private.li2":"Ar c'hemennadennoù prevez etre tud a zo sifret penn-da-benn.","f.private.li3":"Kont ebet, heulier ebet, koukiz ebet.","f.lang.h":"En ho yezh","f.lang.p":"Ouzhpenn 120 yezh, eus an nederlandeg, ar c'hembraeg hag ar japoneg betek ar pirat, Yoda ha klingon, gant ur cheñchamant buan en-dro d'ar saozneg evit gerioù ar grennarzhourien.","tl.aria":"Amzeriadur eus ar c'hentañ kaozeadenn betek ar gevrenn-hent","tl.h2":"Eus ar c'hentañ flap d'ar pezh zo da heul","tl.lede":"Deizioù hag eurioù gwir, en ho takad eur deoc'h-c'hwi. Goude hiziv eo ar plan, hep deiziad ebet prometet.","tl.today":"Hiziv","tl.planned":"bet raktreset","tl.cards.one":"{n} kartenn","tl.cards.other":"{n} kartenn","join.h2":"Deuit ganeomp","join.lede":"AI-gile a vez savet gant un den bihan hag un niver bras a ajanted a-bouez. Prevez eo evit bremañ, en un alfa serret gant mignoned. C'hoant hoc'h eus d'e amprouiñ p'en em zigoro?","join.btn":"Lavarout ho c'hoant","join.small":"Skrivañ a raimp deoc'h dre bostel, netra all","footer.tag":"AI-gile. Heulier ebet, koukiz ebet, kafe stand-up ebet.","footer.licence":"Aotre embregerezh","footer.status":"Stad","form.sending":"O kas…","form.failed":"N'eo ket aet en-dro: klaskit en-dro diwezhatoc'h.","form.offline":"N'eus ket tu da dizhout AI-gile: klaskit en-dro diwezhatoc'h.","interest.title":"AI-gile: lavarit din p'en em zigoro an alfa","interest.description":"Leuskit ho postel evit gouzout p'en em zigoro alfa serret pe beta AI-gile.","interest.h1":"🔔 Lavarit din p'en em zigor","interest.lede":"AI-gile zo e pre-alfa serret. Leuskit ho postel hag e skrivimp deoc'h unwezh, p'en do un plas evidoc'h.","interest.email":"Ho postel","interest.which":"Peseurt amprouadenn?","interest.alpha":"Alfa serret: abred, garv, kalz cheñchamantoù","interest.beta":"Beta: stabiloc'h, diwezhatoc'h","interest.both":"An eil pe egile, an hini a zeu da gentañ","interest.submit":"Lakait ac'hanon war ar roll","interest.thanks":"Trugarez! War ar roll oc'h.","interest.kept":"Ho postel hepken hag an amprouadenn dibabet a vez miret, evit ar roll-mañ hepken. Lizher-keleier ebet, heulier ebet.","licence.title":"AI-gile: aotre embregerezh","licence.description":"Implijout a rit AI-gile en ho embregerezh? Goulennit un aotre embregerezh digoust.","licence.h1":"📜 Aotre embregerezh","licence.lede":"Implijout a rit AI-gile er labour? Lavarit deomp piv oc'h hag petra a rit. M'ober a ra un tammig mat, digoust eo an aotre.","licence.company":"Embregerezh","licence.website":"Lec'hienn","licence.what":"Ar pezh a rit","licence.how":"Penaos e sikour ar bed","licence.email":"Postel","licence.submit":"Goulenn","licence.thanks":"Trugarez! Respont a raimp dre bostel.","status.title":"Stad AI-gile","status.h1":"Stad AI-gile","status.quiet":"Peoc'h an holl","status.checking":"O wiriañ…","status.offline":"N'eus ket tu da dizhout ar servij stad bremañ (o klask en-dro)","status.updated":"hizivaet {ago}","status.justNow":"bremañ just","status.min":"{n} min zo","status.hours":"{n} h zo","status.days":"{n} d zo","live.h2":"Sellit ouzh e vezañ savet, war-eeun","live.caption":"Pep kartenn a zo kuzhet: gwelout a rit stumm al labour, ket ar gerioù.","live.watching.one":"war-eeun: {n} o sellout","live.watching.other":"war-eeun: {n} o sellout","live.offline":"Ur pennad diskuizh a gemer an daolenn war-eeun. Distroit a-benn nebeut.","live.cols":"Backlog|Da ober|O vont war-raok|Ar skipailh a wiriañ|Evidoc'h da test|Evit ar skipailh|Graet"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotoù.","Dilezet."]},{"n":2,"texts":["Kanban robotoù.","Ajanted urzhiet.","Mennozhioù, savet."]},{"n":3,"texts":["Kanban evit robotoù.","Mennozhioù da perzhioù.","Kanban ajanted digoust."]},{"n":5,"texts":["Taolenn kanban rediet gant ajanted.","C'hwi a skriv. Ajanted a sav.","Digoust, lec'hel, amprouet, un tammig sot."]},{"n":8,"texts":["Taolenn kanban digoust, ajanted AI a labour warni.","Skrivit ur mennozh. Ajanted a sav anezhañ. Asantit.","Agile evit un den hag kalz robotoù a-bouez."]},{"n":13,"texts":["Un daolenn kanban war hoc'h urzhiater e vez kemeret ar c'hartennoù gant ajanted AI.","Skrivit ur mennozh. Ur skipailh ajanted a sav anezhañ. Un amprouer a wiriekaat.","Digoust, kont ebet, heulier ebet: un daolenn, un nebeut robotoù, hag c'hwi a gomz."]},{"n":21,"texts":["AI-gile zo un daolenn kanban evit labourat gant ajanted AI a god. Kemer a reont ar c'hartennoù; c'hwi a amprouf hag a asant anezho.","Pep raktres en deus ur penn-skipailh hag ur skipailh ajanted AI. Skrivit un evezhiadenn war ur gartenn ha krog a ra ar skipailh.","Un daolenn labourioù personel ha digoust a red war hoc'h urzhiater deoc'h-c'hwi. Robotoù eo al labourerien. An hini a lavar ya eo c'hwi."]},{"n":34,"texts":["Lakaat a rit mennozhioù war un daolenn. Ur skipailh ajanted AI a laka anezho da perzhioù o labourat, a amprouf anezho, hag a gas en-dro anezho deoc'h gant pazennoù da amprouiñ. Tra ebet n'eo echu a-raok ma lavarit.","AI-gile zo un daolenn kanban graet er gêr gant Rich, gant kalz skoazell eus an ajanted a gas bremañ. Digoust eo, a red war hoc'h urzhiater, hag a vez rannet gant mignoned, n'eo ket gwerzhet.","Soñjit en un daolenn kanban boas, gant bannoù eus ar Backlog betek Graet, nemet ar c'hartennoù a vez kemeret gant ajanted AI. Displegañ a reont o araokadenn, goulenn m'int stag, ha gortoz atav ho tudenn war-laez."]},{"n":55,"texts":["AI-gile zo un daolenn kanban m'eo ajanted AI ar skipailh. Pep raktres en deus ur penn-skipailh a blan al labour ha skoazelloù a sav anezhañ. Pa vez prest ur perzh, un amprouer AI a amprouf anezhañ hag a ra ur skeudenn skramm, goude-se e teu en ho pern. Asantit anezhañ, pe skrivit un evezhiadenn hag e adober a raint.","Krog eo bet evel un doare evit un den da heuliañ kalz estrenvaoù kodiñ AI war un dro, ha kresket eo e daolenn wirion. Ober a ra war ho jestr, n'en deus ket ezhomm eus kont, ha n'en deus heulier ebet. Digoust eo evit mignoned ha re c'hoant-gouzout. N'eo ket echu c'hoazh, setu gortozit riblennoù garv hag un souezh a-wechoù.","Setu ar stumm onest. Ret eo deoc'h kaout ar mennozhioù c'hoazh, ha gwiriañ an disoc'hoù c'hoazh. Ar pezh a ra AI-gile eo pep tra etre an daou: miret a ra ar c'hartennoù en urzh, dihuniñ a ra an ajant mat pa skrivit un evezhiadenn, diskouez a ra egzakt ar pezh zo cheñchet, ha lakaat a ra an holl en ur bern berr evidoc'h."]},{"n":89,"texts":["AI-gile zo un daolenn kanban digoust a lañsit war hoc'h urzhiater deoc'h-c'hwi. En tu all d'an dud, pep raktres en deus ur skipailh ajanted AI: ur penn-skipailh a laka ho mennozhioù da gartennoù ha da blan, ha skoazelloù a gemer ar c'hartennoù hervez o raktres. Pa vez savet un dra bennak, un amprouer AI a heul ar pazennoù amprouiñ hag a ziskouez deoc'h ar pezh en deus gwelet. Goude-se e c'hortoz en ur bern anvet Evidoc'h. Asantiñ a rit, pe skrivit un evezhiadenn hag ar skipailh a glask en-dro. Tra ebet ne zeu da Graet hep c'hwi.","Un nebeut traoù na c'hortozit ket marteze. Ur gward-noz a vir ar bann Da ober leun p'emaoc'h o kousket, o tibab kartennoù na c'houlennont ket respont diganeoc'h. Ur jedour tokenoù a ziskouez pet en deus implijet an ajanted hiziv hag ar sizhun-mañ, ha No Token Mode a lavar dezho paouez da zispign. Gallout a rit skrivañ da vignoned, ha sifret eo ar c'hemennadennoù prevez penn-da-benn. An daolenn a gomz tro-dro 120 yezh, en o zouez nederlandeg, flamanteg, pirat ha klingon. Netra eus se ne gousto ur gwenneg, ha den n'eo o klask gwerzhañ se deoc'h.","AI-gile zo ur raktres bihan, personel, n'eo ket un embregerezh. C'hoant en doa Rich da ober war-dro meur a raktres kodiñ AI hep digeriñ pep arload evit o gwiriañ, setu en deus savet gant an ajanted un daolenn evit se, hag implijet an daolenn evit sevel ar rest anezhi. E pre-alfa serret emañ, da lavaret eo e vez mat, dre vras, evit ur bochad mignoned. Pajenn priz ebet, lizher-keleier ebet, plan kresk ebet. M'hoc'h eus c'hoant, gallout a rit goulenn e amprouiñ p'en em zigoro un tammig muioc'h."]},{"n":144,"texts":["AI-gile zo un daolenn kanban evit un den ha kalz ajanted AI. Red a ra war hoc'h urzhiater deoc'h-c'hwi ha digoust eo penn-da-benn. Ouzhpennañ a rit raktresoù, ha pep raktres a zeu gant ur penn-skipailh hag ur skipailh bihan. Flapañ a rit gant ar penn-skipailh, un tammig evel war Discord, ha deskrivañ ur mennozh; ar penn-skipailh a laka anezhañ da gartennoù ha da blan, goude-se e c'hortoz ma wasit war Go. Ar skipailh a labour ar c'hartennoù hervez o raktres, dre un urzhiad-linenn simpl graet evit modeloù yezh. Kent ma teuio tra ebet en-dro deoc'h, un amprouer AI a heul ar pazennoù en un eilad eus an arload hag a stag ur skeudenn skramm. Al labour echu a zeu en ho pern gant ar restroù cheñchet hag an diforc'h. Asantiñ a rit, pe skrivit un evezhiadenn hag ar skipailh a zihun hag a glask en-dro. Hepken c'hwi a c'hall dilec'hiañ ur gartenn da Graet. Kont ebet, heulier ebet, koukiz ebet, ha pep tra a chom war hoc'h urzhiater.","Un devezh gant AI-gile, tro-dro. Da noz e lezit un nebeut evezhiadennoù: ar bouton-mañ zo e plas fall, ar roll-se a rankfe bezañ rummet, ha ne vefe ket un doare teñval. Mont a rit da gousket. An ajanted a lenn an evezhiadennoù, a ra ar cheñchamantoù, a amprouf anezho hag a gas en-dro deoc'h. Ma teu Da ober da vezañ goullo, ar gward-noz a leun anezhañ diwar ar backlog gant kartennoù na c'houlennont ket respont diganeoc'h. Da vintin ur bern berr zo: un nebeut goulennoù hag un nebeut traoù da amprouiñ, pep hini gant pazennoù a c'hall heuliañ un den kousket-koazh ha gant ur skeudenn skramm eus an dra o labourat. Klikañ a rit dre-hont, asantiñ ar re vat ha kas en-dro ar re all. Ur jedour tokenoù a ziskouez ar pezh en deus implijet an holl, ha No Token Mode zo evit ar sizhunioù treut. Goude-se e tebrit ho pred-vintin, ha n'hall ket an ajanted sikour ac'hanoc'h c'hoazh.","Da gentañ, petra n'eo ket AI-gile. N'eo ket ur startup, n'eo ket da werzhañ, ha den ne zastum ho roadennoù. Un daolenn digoust eo a red war hoc'h urzhiater, hep kont, hep heulier ha hep koukiz. Ar pezh eo: ur plas kempenn m'hallit gwelet holl raktresoù kodiñ AI war un dro, gant ur skipailh ajanted a ra ar c'hartennoù ha c'hwi a ra an divizoù. Kenstrollañ a ra ar c'hartennoù kar, reizhañ a ra an titloù mesk, ha selaou a ra penaos e chom skañv ar c'hod. Komz a ra tro-dro 120 yezh, eus an nederlandeg hag ar flamanteg betek ar pirat hag ar c'hlingon. Ar mignoned a c'hall skrivañ an eil d'egile, e prevez ha sifret. Savet eo bet gant Rich hag un niver bras a ajanted a-bouez, dre implijout e-unan peurliesañ. E pre-alfa serret emañ, setu garv eo a-wechoù. M'hoc'h eus c'hoant, goulennit gant jentilezh ha marteze e vo digor deoc'h abred."]}],"quips":{"1":"Ur ger. Dispont. Re zispont marteze.","3":"Tri ger. Muioc'h onest dija eget an darn vrasañ eus ar pajennoù produioù.","8":"Eizh ger. Berroc'h c'hoazh eget ur stand-up.","21":"Ar hirderioù zo story points, dre-vras. Evel just e int.","55":"Pemp ha hanter-kant ger. Div gartenn zo bet echu e-keit ha ma lennit.","144":"Honnezh eo an hini hir. 233 ebet. An ajanted zo aet da gousket."}},"timeline":{"first-idea.name":"Ar c'hentañ mennozh","first-idea.line":"Ar c'hentañ kaozeadenn a-bezh, a-raok ma vije kod ebet.","first-board.name":"Ar c'hentañ taolenn","first-board.line":"Un daolenn a heul he c'hrouidigezh: kartennoù, bannoù, riklañ-ha-lezel, raktresoù.","team-roles.name":"Skipailh ha rolloù","team-roles.line":"Profiloù ajanted, patromoù skipailh, plasoù ha piv a ra petra.","install.name":"Staliañ ha stummoù","install.line":"Ur zip a c'hall ur mignon staliañ, hizivadur emgefreek, kanolioù ha distro d'ar penn-kentañ.","usage-saver.name":"Espern implij","usage-saver.line":"Muzuliañ ar pezh a gousto ar redadennoù, mirout ar c'hod skañv, espern ho harzh.","friends.name":"Mignoned ha rannañ","friends.line":"Kemennadennoù prevez, un adlavar sifret, pedadennoù, rolloù ha raktresoù rannet.","languages.name":"Yezhoù","languages.line":"Pep skrid skramm en ur restr yezh, an nederlandeg hag ar flamanteg da gentañ.","ai-tester.name":"Amprouer AI","ai-tester.line":"Un amprouer a wiriekaat pep treuzkas da gentañ hag a ziskouez ar pezh en deus gwelet.","website.name":"al lec'hienn","website.line":"aigile.lol, ar rakskeudenn hag an amzeriadur-mañ.","streaming.name":"Flap ha streamiñ","streaming.line":"Discord, Twitch, OBS, mod streamer, GIFoù hag emojioù.","no-ai.name":"Stumm hep AI","no-ai.line":"Un daolenn evit tud a god hep AI, ha taolennoù foran.","night-watch.name":"Gward-noz","night-watch.line":"Ur gward ha Scrum Master a vir ar skipailhoù war al labour p'emaoc'h o kousket.","p-more.name":"Kement tra all","p-more.line":"Mennozhioù bihanoc'h a c'hortoz c'hoazh o zro.","p-android.name":"Pellgomzer ha Android","p-android.line":"Tizhout ho taolenn diwar ur pellgomzer, goude-se un arload Android a-orin.","p-release.name":"Alfa ha pelloc'h","p-release.line":"Alfa serret, al lec'hienn vev, goude-se beta.","p-languages.name":"Muioc'h a yezhoù","p-languages.line":"Ouzhpenn kant yezh, ha mod beuzañ evit an dud a zesk.","p-engines.name":"Muioc'h a vekanikoù AI","p-engines.line":"Dibab Claude, Codex pe Gemini evit pep ajant.","p-pro.name":"Boaz a vicherour","p-pro.line":"Skritelloù riskl, dorioù kenaozañ, kartennoù darvoud ha bannoù-diwall.","p-self.name":"Kempenn ac'hanoc'h","p-self.line":"Mod skuizh, kemennoù evit ober war-dro ac'hanoc'h ha 4:20.","p-servers.name":"Servijerioù ha brasaat","p-servers.line":"Arventennoù servijer hollek, rolloù ha plan evit kreskiñ.","p-livestream.name":"Ouzhpennoù streamiñ","p-livestream.line":"Flap Twitch, emojioù personel ha gwel foran bev."}};
